result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/culling.js", "content": "import {
  Box3,
  Frustum,
  Matrix4,
  Sphere
} from 'three';

/**
 * Key under which each object's world-space bounding sphere is cached in
 * `object.userData`.
 */
export const CULL_SPHERE_CACHE_KEY = '__cullingBoundingSphere';

/**
 * Invalidate the cached bounding sphere of an object (and its descendants).
 *
 * MUST be called whenever an object (or any of its children) moves, is
 * scaled, or has its geometry replaced. The next call to `visibleSet` /
 * `cullStats` will then recompute the sphere from the new world transform.
 */
export function invalidateCullCache(object) {
  if (!object) return;
  if (object.userData) delete object.userData[CULL_SPHERE_CACHE_KEY];
  for (const child of object.children) invalidateCullCache(child);
}

/**
 * Compute (or fetch from cache) the object's world-space bounding sphere.
 * The sphere is computed once per (in)validation cycle and stored on
 * `object.userData`, so repeated frames over a large gallery scene do not
 * re-walk geometries.
 */
function getCachedWorldSphere(object) {
  const cached = object.userData?.[CULL_SPHERE_CACHE_KEY];
  if (cached instanceof Sphere) return cached;

  object.updateWorldMatrix(true, true);
  const box = new Box3().setFromObject(object);
  const sphere = new Sphere();
  box.getBoundingSphere(sphere);
  object.userData[CULL_SPHERE_CACHE_KEY] = sphere;
  return sphere;
}

/** Build a world-space THREE.Frustum from the camera's current state. */
function frustumFromCamera(camera) {
  camera.updateProjectionMatrix();
  camera.updateMatrixWorld(false); // Camera.updateMatrixWorld also refreshes matrixWorldInverse
  const viewProj = new Matrix4().multiplyMatrices(
    camera.projectionMatrix,
    camera.matrixWorldInverse
  );
  return new Frustum().setFromProjectionMatrix(viewProj);
}

/**
 * Return the array of objects whose world-space bounding spheres intersect
 * the camera's frustum.
 *
 * @param {THREE.PerspectiveCamera|THREE.Camera} camera
 * @param {THREE.Object3D[]} objects
 * @returns {THREE.Object3D[]} visible objects (same order as input)
 */
export function visibleSet(camera, objects) {
  const frustum = frustumFromCamera(camera);
  const visible = [];
  for (const object of objects) {
    if (frustum.intersectsSphere(getCachedWorldSphere(object))) {
      visible.push(object);
    }
  }
  return visible;
}

/**
 * Same query as `visibleSet`, but returns aggregate counts.
 *
 * @returns {{visible: number, culled: number}}
 */
export function cullStats(camera, objects) {
  const visible = visibleSet(camera, objects).length;
  return { visible, culled: objects.length - visible };
}
