result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/culling.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { visibleSet, cullStats, invalidateCullCache } from '../src/culling.js';

const FOV = 60;
const ASPECT = 1;
const NEAR = 0.1;
const FAR = 100;

function makeCamera() {
  const camera = new THREE.PerspectiveCamera(FOV, ASPECT, NEAR, FAR);
  camera.position.set(0, 0, 0);
  camera.lookAt(0, 0, -1); // facing -z
  return camera;
}

function sphereAt(x, y, z, radius = 1) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, 16, 16));
  mesh.position.set(x, y, z);
  mesh.updateMatrixWorld(true);
  return mesh;
}

// Half-width of the frustum at a given -z distance (aspect = 1).
const halfWidthAt = (distance) =>
  Math.tan(THREE.MathUtils.degToRad(FOV / 2)) * ASPECT * distance;

describe('visibleSet', () => {
  it('culls in front/behind/outside correctly for a camera at origin facing -z', () => {
    const camera = makeCamera();

    // Definitely outside the horizontal fov at that depth:
    const outX = -(halfWidthAt(10) + 2); // 2 units beyond the frustum edge
    const objects = [
      sphereAt(0, 0, -10),          // straight ahead -> visible
      sphereAt(0, 0, 10),           // behind the near plane -> culled
      sphereAt(0, 0, -200),         // beyond far plane -> culled
      sphereAt(outX, 0, -10)        // just outside horizontal fov -> culled
    ];

    const visible = visibleSet(camera, objects);
    expect(visible).toHaveLength(1);
    expect(visible[0]).toBe(objects[0]);
  });

  it('counts a huge object overlapping the frustum edge as visible', () => {
    const camera = makeCamera();
    // Center well outside the fov at z=-10, radius large enough to overlap.
    const center = -(halfWidthAt(10) + 5);
    const huge = sphereAt(center, 0, -10, 20);
    const visible = visibleSet(camera, [huge]);
    expect(visible).toContain(huge);
  });

  it('recomputes cached spheres after invalidation when an object moves', () => {
    const camera = makeCamera();
    const obj = sphereAt(0, 0, -10);

    expect(visibleSet(camera, [obj])).toContain(obj);

    // Move it behind the camera; without invalidation the stale cached
    // sphere would still report it as visible.
    obj.position.set(0, 0, 10);
    invalidateCullCache(obj);
    expect(visibleSet(camera, [obj])).not.toContain(obj);

    // And back into view again.
    obj.position.set(0, 0, -50);
    invalidateCullCache(obj);
    expect(visibleSet(camera, [obj])).toContain(obj);
  });
});

describe('cullStats', () => {
  it('returns stats whose visible + culled equals the object count', () => {
    const camera = makeCamera();
    const objects = [
      sphereAt(0, 0, -10),
      sphereAt(0, 0, 10),
      sphereAt(0, 0, -200),
      sphereAt(-(halfWidthAt(10) + 3), 0, -10),
      sphereAt(halfWidthAt(10) / 2, 0, -10)
    ];

    const stats = cullStats(camera, objects);
    expect(stats.visible).toBe(2);
    expect(stats.culled).toBe(3);
    expect(stats.visible + stats.culled).toBe(objects.length);
  });
});
"})
